from pathlib import Path
from html import escape

root=Path(__file__).resolve().parent
pages={}

def hero(kicker,title,summary,image):
    real=image=='site-ballow-aerial.webp'
    alt='Actual aerial photograph of the 10-12 Ballow Road candidate site' if real else 'Illustrative Sandy Sports scene'
    caption='Actual Ballow Road site photo; other sites are not depicted.' if real else 'Concept illustration; no facility or event is confirmed.'
    return f'<section class="page-hero"><img src="/assets/{image}" alt="{alt}"><div class="page-hero-copy"><p class="eyebrow light">{kicker}</p><h1>{title}</h1><p>{summary}</p></div><small class="caption">{caption}</small></section>'

def cards(items,columns=''):
    out=f'<div class="card-grid {columns}">'
    for tag,title,copy,img,href in items:
        alt='Actual aerial photo of 10-12 Ballow Road in Dunwich (Goompi)' if img=='site-ballow-aerial.webp' else 'Illustrative scene'
        photo=f'<img src="/assets/{img}" alt="{alt}" loading="lazy">' if img else ''
        link=f'<a href="{href}">Explore further</a>' if href else ''
        out+=f'<article class="card">{photo}<div class="inner"><span class="tag">{tag}</span><h3>{title}</h3><p>{copy}</p>{link}</div></article>'
    return out+'</div>'

def section(kicker,title,body,extra='',tone=''):
    return f'<section class="page-section {tone}"><p class="eyebrow">{kicker}</p><h2>{title}</h2><p class="lead">{body}</p>{extra}</section>'

def put(slug,title,description,content,script=''):
    js=f'<script src="/{script}" defer></script>' if script else ''
    pages[slug]=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#102d40"><meta name="description" content="{escape(description,quote=True)}"><title>{title} | Sandy Sports Club proposal</title><link rel="icon" href="/favicon.png" type="image/png"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/pages.css"><script src="/site.js" defer></script>{js}</head><body><div data-site-header></div><main id="main">{content}</main><div data-site-footer></div></body></html>'''

put('index.html','One island, many arenas','An ambitious mixed sand sports and cultural club proposal across Dunwich (Goompi), Amity Point (Pulan) and Point Lookout (Mulumba).',
    hero('MINJERRIBAH · NORTH STRADBROKE ISLAND','One island.<br>Three towns.<br>World-class possibilities.','A proposed network of adaptable sand sport facilities, clubhouses and cultural spaces. Mixed beach volleyball leads, with flag football, cricket, rugby and more sharing the surface. Island clubs keep their identities and gain another arena.','hero-home.webp')+
    section('THE CLUB WE COULD BUILD','A sporting island with room to grow','Think local weekly play, major invitationals, youth pathways, mixed leagues and international cultural exchange. Imagine a connected Dunwich (Goompi), Amity Point (Pulan) and Point Lookout (Mulumba) programme, with facilities chosen for fit and resilience.',cards([
      ('THE ANCHOR','Mixed beach volleyball','Social, club and high-performance pathways with flexible doubles and mixed formats.','hero-sports.webp','/sport-mixed-beach-volleyball.html'),
      ('A BIG OPPORTUNITY','Flag football','A non-contact sport with significant US and Australian development behind it, and a Brisbane 2032 ambition.','flag-football-concept.webp','/flag-football.html'),
      ('THREE TOWNS','Distributed facilities','Complementary venues and portable equipment make the club useful across the island.','','/places.html')]))+
    section('A CAMPUS, NOT JUST A COURT','Sport, screen, market and culture','A tournament can flow into a local film screening, makers market or multicultural expo. A separate film club inside Sandy Sports gives creators their own programme and equipment stewardship.',cards([
      ('FACILITIES','Adaptable clubhouses','Demountable and extendable container modules, dressing rooms, showers, storage, lighting and event infrastructure.','hero-trust.webp','/facilities.html'),
      ('FILM CLUB','A screen in many forms','A permanent LED screen concept and mobile, segmentable panels for club nights, smaller screens and potential hire.','modular-led-concept.webp','/film-club.html'),
      ('CAPITAL','Public and private backing','Council, state and federal grants, First Nations-led opportunities, foundations, sponsorship and investment each have a role.','hero-funding.webp','/grants.html')]),'alt')+
    section('CLUBHOUSE SYSTEMS','People and an operating system','Explore proposed member, committee and Webmaster areas adapted from the Point Lookout Fishing Club clubhouse. The demo records are examples; Sandy Sports has not opened membership or appointed officers.',cards([
      ('MEMBERS','A home for players','Teams, calendar, notices, learning, family profiles, competitions and cross-club invitations.','','/members.html'),
      ('COMMITTEE','Organise together','Agendas, decisions, jobs, facilities, grant evidence, assets and programmes by role.','','/committee.html'),
      ('WEBMASTER','Keep it coherent','Content review, accounts, permissions, publication, audits and an isolated demo workspace.','','/webmaster.html')]))+
    section('BRISBANE 2032 HORIZON','Build an island-scale legacy','Training camps, mixed competitions, school-to-club pathways and sand sport expos can connect island participation to the wider sporting decade. No Games venue designation or organiser relationship is claimed.','<div class="link-row"><a class="button coral" href="/sports.html">Explore every sport</a><a class="button outline" href="/places.html">Explore the sites</a><a class="button outline" href="/clubhouse.html">Open the clubhouse map</a></div>','sunny')+
    section('JOIN THE BUILD','Nominate, organise, back the assets','Summer is a chance to assemble the founding team, partner clubs and first programme. Put your hand up for membership, a committee role, a film crew, a sport desk or a founding contribution.','<div class="link-row"><a class="button coral" href="/join.html">Nominate to join</a><a class="button outline" href="/donate.html">Explore the screen campaign</a></div>'))

