funding_model='''<div class="fundraiser"><div><span class="tag">ILLUSTRATIVE CAMPAIGN</span><h3>Modular LED screen equipment</h3><p class="funding-big" id="funding-total">$0 <small>of $50,000 example target</small></p><div class="progress-track" role="progressbar" aria-label="Illustrative fundraising progress" aria-valuemin="0" aria-valuemax="50000" aria-valuenow="0" id="funding-progress"><span id="funding-bar"></span></div><p id="funding-percent" class="form-tip">0% of example target. No donations have been recorded here.</p><div class="form-grid"><label>Example community gifts<input type="number" id="gift-count" min="0" max="50000" value="40"></label><label>Average gift (AUD)<input type="number" id="gift-value" min="0" max="50000" value="100"></label><label>Example founding sponsors<input type="number" id="sponsor-count" min="0" max="1000" value="4"></label><label>Average sponsorship (AUD)<input type="number" id="sponsor-value" min="0" max="500000" value="5000"></label><label>Example grant contribution (AUD)<input type="number" id="grant-value" min="0" max="1000000" value="15000"></label></div><button class="button outline" type="button" id="reset-funding">Reset example</button></div><aside class="fundraiser-breakdown"><h3>What the example means</h3><p>The inputs illustrate <strong>pledges and funding scenarios</strong>. They are not a live donation ledger, confirmed grants or money held.</p><div id="funding-mix" class="funding-mix"></div><p class="funding-remaining" id="funding-remaining"></p><p>For a large, fixed outdoor screen, engineering, supports, electrical work, permits and installation need a separate site quote and potentially a much larger budget.</p></aside></div>'''
put('donate.html','Donations and screen campaign','An illustrative $50,000 modular LED screen fundraising target, pricing context and ways to support.',
    hero('FUND THE ISLAND SCREEN NETWORK','One display. Many sizes. Many stories.','Back a modular outdoor LED fleet that can become a main cinema wall, split into smaller screens for clubs and events, and support live sport and film production across three towns.','modular-led-concept.webp')+
    section('CAMPAIGN VISUALISATION','$50,000 equipment example','Change the gifts, sponsorship and grant amounts to explore a funding mix. The counter is a scenario, not money collected. A formal donations campaign needs an eligible recipient, approved account, terms and live reporting.',funding_model,'sunny')+
    section('SCREEN OPTIONS','Price the LED system as a system','The proponent previously saw an approximately $45,000 direct-import indication, but its specification and current price have not been verified. The $50,000 counter is a fundraising example, not a quote or a chosen screen size. Obtain current factory quotations for panel count and pixel pitch, processor, spare modules, freight, duties, power and warranty, then separately price engineered supports, installation, weather protection, servicing and approvals. The existing 6 m inflatable projection screen is different equipment and is not a modular LED wall.','<div class="link-row"><a class="button outline" href="/assets.html">Screen asset system</a><a class="button outline" href="/film-club.html">Film club uses</a></div>','alt')+
    section('WAYS TO HELP','Pledge a contribution or a capability','The organiser can discuss founding gifts, sponsorship, equipment, transport, technical support, screen programming or grant partnerships. Email an expression of interest; the proposal site does not take payments or issue tax receipts.','<div class="link-row"><a class="button coral" href="mailto:sbt4183@gmail.com?subject=Sandy%20Sports%20screen%20support">Email a screen pledge</a><a class="button outline" href="/join.html">Join the founding team</a><a class="button outline" href="/assets.html">Full asset wish list</a></div>'),'funding.js')

